UPDATE t_employee_reporting
SET status = 'ENDED', active_direct_marker = NULL,
    version = version + 1, edit_time = #{effectiveAt}, edit_by = #{editBy}
WHERE subordinate_employee_id = #{subordinateEmployeeId}
  AND status = 'ACTIVE'
  AND effective_to IS NOT NULL
  AND effective_to <= #{effectiveAt}

UPDATE t_employee_reporting
SET status = 'ENDED', active_direct_marker = NULL,
    version = version + 1, edit_time = #{effectiveAt}, edit_by = #{editBy}
WHERE subordinate_employee_id = #{subordinateEmployeeId}
  AND relation_type = 'ACTING'
  AND status = 'ACTIVE'
  AND effective_to IS NOT NULL
  AND effective_to <= #{effectiveAt}

UPDATE t_employee_reporting
SET status = 'ENDED',
    active_direct_marker = NULL,
    effective_to = #{effectiveTo},
    version = version + 1,
    edit_time = #{editTime},
    edit_by = #{editBy}
WHERE id = #{reportingId}
  AND version = #{expectedVersion}
  AND status IN ('PLANNED', 'ACTIVE')
  AND (effective_to IS NULL OR effective_to > #{effectiveTo})
  AND effective_from < #{effectiveTo}

UPDATE t_employee_reporting
SET status = 'CANCELLED',
    active_direct_marker = NULL,
    version = version + 1,
    edit_time = #{editTime},
    edit_by = #{editBy}
WHERE id = #{reportingId}
  AND version = #{expectedVersion}
  AND status IN ('PLANNED', 'ACTIVE')
  AND effective_from >= #{effectiveAt}
